type VideoItem = {
  id: string;
  title: string;
  topic: string;
  createdAt: string;
  videoUrl: string | null;
};

type VideoGridProps = {
  items: VideoItem[];
};

export function VideoGrid({ items }: VideoGridProps) {
  if (!items.length) {
    return <p className="text-sm text-steel">No videos generated yet.</p>;
  }

  return (
    <div className="grid gap-4 md:grid-cols-2">
      {items.map((item) => (
        <div key={item.id} className="brutal-card p-4 space-y-3">
          <div>
            <p className="text-xs uppercase tracking-wide text-steel">{item.topic}</p>
            <h3 className="text-lg font-semibold">{item.title || "Untitled"}</h3>
            <p className="text-xs text-steel">{new Date(item.createdAt).toLocaleString()}</p>
          </div>
          {item.videoUrl ? (
            <video controls className="w-full border-2 border-ink">
              <source src={item.videoUrl} type="video/mp4" />
            </video>
          ) : (
            <div className="text-sm text-steel">Video unavailable.</div>
          )}
        </div>
      ))}
    </div>
  );
}
