"use client";

import { useEffect, useState } from "react";
import { StepStatus } from "../components/StepStatus";
import { VideoGrid } from "../components/VideoGrid";

const steps = ["Generating script", "Fetching images", "Generating audio", "Rendering video"];

type VideoItem = {
  id: string;
  title: string;
  topic: string;
  createdAt: string;
  videoUrl: string | null;
};

export default function Home() {
  const [topic, setTopic] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [activeStep, setActiveStep] = useState(0);
  const [currentVideo, setCurrentVideo] = useState<string | null>(null);
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [error, setError] = useState<string | null>(null);

  const apiBase = process.env.NEXT_PUBLIC_API_BASE || "http://localhost:4000";

  const loadVideos = async () => {
    const response = await fetch(`${apiBase}/api/videos`);
    const data = await response.json();
    setVideos(data.items || []);
  };

  useEffect(() => {
    loadVideos();
  }, []);

  useEffect(() => {
    if (!isLoading) {
      return;
    }
    let stepIndex = 0;
    setActiveStep(stepIndex);
    const timer = setInterval(() => {
      stepIndex += 1;
      setActiveStep(Math.min(stepIndex, steps.length - 1));
    }, 1800);
    return () => clearInterval(timer);
  }, [isLoading]);

  const handleGenerate = async () => {
    if (!topic.trim()) {
      setError("Enter a topic first.");
      return;
    }
    setError(null);
    setCurrentVideo(null);
    setIsLoading(true);
    setActiveStep(0);

    try {
      const response = await fetch(`${apiBase}/api/videos/generate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ topic })
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || "Failed to generate video");
      }
      setCurrentVideo(data.videoUrl || null);
      await loadVideos();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main className="min-h-screen px-6 py-10 md:px-16">
      <div className="max-w-5xl mx-auto space-y-10">
        <section className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
          <div className="brutal-card p-6 space-y-6">
            <div className="space-y-2">
              <p className="text-xs uppercase tracking-[0.3em] text-steel">AI Video Lab</p>
              <h1 className="text-4xl md:text-5xl font-semibold leading-tight">
                Topic to Brutalist Video in Minutes
              </h1>
              <p className="text-steel text-sm">
                Feed a topic, get a stitched slideshow with audio. Cached by topic hash for instant reruns.
              </p>
            </div>

            <div className="space-y-4">
              <input
                className="brutal-input w-full"
                placeholder="Enter a topic like 'Future of solar cities'"
                value={topic}
                onChange={(event) => setTopic(event.target.value)}
              />
              <button
                className="brutal-button px-6 py-3 font-semibold uppercase tracking-wide"
                onClick={handleGenerate}
                disabled={isLoading}
              >
                {isLoading ? "Working..." : "Generate Video"}
              </button>
              {error ? <p className="text-sm text-red-600">{error}</p> : null}
            </div>

            {currentVideo ? (
              <div className="space-y-3">
                <h2 className="text-lg font-semibold">Latest Render</h2>
                <video controls className="w-full border-2 border-ink">
                  <source src={currentVideo} type="video/mp4" />
                </video>
                <a
                  className="brutal-button inline-flex items-center px-4 py-2 text-sm"
                  href={currentVideo}
                  download
                >
                  Download MP4
                </a>
              </div>
            ) : null}
          </div>

          <div className="space-y-4">
            <div className="brutal-card p-6">
              <h2 className="text-lg font-semibold mb-4">Pipeline</h2>
              <StepStatus steps={steps} activeIndex={isLoading ? activeStep : -1} />
            </div>
            <div className="brutal-card p-6 text-xs uppercase tracking-wide text-steel">
              <p>Single Gemini call · Max 2 images per section · Local storage MVP</p>
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-2xl font-semibold">Previous Videos</h2>
          <VideoGrid items={videos} />
        </section>
      </div>
    </main>
  );
}
